import assert from 'node:assert/strict';
import { createShop } from './src/inventory-reservations/index.mjs';
import { createClient } from './src/retry-idempotency/client.mjs';
import { Ledger } from './src/atomic-ledger/ledger.mjs';

// Inventory combines semantic duplicates, namespaces request ids, and publishes atomically.
const initial = { t1: { a: 10, b: 4 }, t2: { a: 10 } };
const shop = createShop(initial);
const input = { tenant: 't1', requestId: 'same', items: [{ sku: 'a', quantity: 1 }, { sku: 'a', quantity: 2 }] };
const receipt = shop.reserve(input);
assert.deepEqual(receipt.items, [{ sku: 'a', quantity: 3 }]);
assert.equal(shop.stock('t1', 'a'), 7);
assert.deepEqual(shop.reserve({ ...input, items: [...input.items].reverse() }), receipt);
shop.reserve({ tenant: 't2', requestId: 'same', items: [{ sku: 'a', quantity: 2 }] });
assert.equal(shop.stock('t2', 'a'), 8);
assert.equal(initial.t1.a, 10);
assert.throws(() => shop.reserve({ tenant: 't1', requestId: 'failed', items: [{ sku: 'a', quantity: 2 }, { sku: 'b', quantity: 5 }] }));
assert.equal(shop.stock('t1', 'a'), 7);
shop.reserve({ tenant: 't1', requestId: 'failed', items: [{ sku: 'a', quantity: 1 }] });

// POST key stays fixed across retries, caller key wins, Retry-After seconds become milliseconds.
const calls = [], sleeps = [];
let keyCalls = 0, n = 0;
const post = createClient({
  transport: async req => { calls.push(req); return { status: ++n === 1 ? 429 : 200, headers: { 'Retry-After': '2' } }; },
  sleep: async ms => sleeps.push(ms), keyFactory: () => `key-${++keyCalls}`,
});
await post({ method: 'POST', url: '/x' });
assert.equal(keyCalls, 1);
assert.equal(calls[0].headers['idempotency-key'], calls[1].headers['idempotency-key']);
assert.deepEqual(sleeps, [2000]);
let explicitKeyFactoryCalls = 0;
const explicit = createClient({ transport: async req => req, sleep: async () => {}, keyFactory: () => ++explicitKeyFactoryCalls });
assert.equal((await explicit({ method: 'POST', url: '/x', headers: { 'Idempotency-Key': 'provided' } })).headers['Idempotency-Key'], 'provided');
assert.equal(explicitKeyFactoryCalls, 0);

// Ledger batch rollback and intra-batch idempotency.
const ledger = new Ledger({ a: 100, b: 0 });
const result = ledger.applyBatch([
  { id: 'one', from: 'a', to: 'b', amount: 20 },
  { id: 'one', from: 'a', to: 'b', amount: 20 },
]);
assert.deepEqual(result, { a: 80, b: 20 });
assert.notEqual(result, ledger.snapshot());
assert.throws(() => ledger.applyBatch([
  { id: 'two', from: 'a', to: 'b', amount: 10 },
  { id: 'three', from: 'b', to: 'c', amount: 1 },
]));
assert.deepEqual(ledger.snapshot(), { a: 80, b: 20 });
assert.deepEqual(ledger.applyBatch([{ id: 'two', from: 'a', to: 'b', amount: 10 }]), { a: 70, b: 30 });
EOF
